import {writeFileSync} from 'node:fs';
import {simulateStoryFloor,STORY_COMPOSITIONS,STORY_BALANCE_FIXTURE} from '../scripts/tower-story-balance-sim.js';
const report={fixture:STORY_BALANCE_FIXTURE,startedAt:new Date().toISOString(),routes:[],freshFinales:[],solo:[],highRoll:[],failures:[]};
const save=()=>writeFileSync('.tmp/tower-pve-combined-main-curve.json',JSON.stringify(report,null,2));
for(const routeChoice of ['rest-shrine','focused-assault','elite-shortcut'] as const){
 for(const composition of STORY_COMPOSITIONS){
  for(let floor=1;floor<=15;floor++){
   const row=simulateStoryFloor(floor,4,12,undefined,composition,true,{routeChoice});report.routes.push(row);
   if(routeChoice==='rest-shrine' && (row.winRate<(floor===15?.5:.7)||row.rounds<5||row.rounds>24))report.failures.push(row);
   save();
  }
  console.log('Completed '+routeChoice+' / '+composition);
 }
}
for(const composition of STORY_COMPOSITIONS){
 report.freshFinales.push(simulateStoryFloor(15,4,24,100,composition,true,{seedOffset:12}));save();
 for(const floor of [13,14,15]) report.highRoll.push(simulateStoryFloor(floor,4,12,undefined,composition,true,{routeChoice:'elite-shortcut',gearProfile:'high-roll'}));save();
}
for(const floor of [1,5,10,15]){report.solo.push(simulateStoryFloor(floor,1,12));save();}
report.finishedAt=new Date().toISOString();save();
console.log(JSON.stringify({runs:report.routes.reduce((s,r)=>s+r.seeds,0),wins:report.routes.reduce((s,r)=>s+r.wins,0),failures:report.failures,freshFinales:report.freshFinales,solo:report.solo}));

import {writeFileSync} from 'node:fs';
import {simulateStoryFloor,STORY_COMPOSITIONS,STORY_BALANCE_FIXTURE} from '../scripts/tower-story-balance-sim.js';
const report={fixture:STORY_BALANCE_FIXTURE,startedAt:new Date().toISOString(),alternateGear:[],lowerPowerControls:[]};
const save=()=>writeFileSync('.tmp/tower-pve-combined-main-alternates.json',JSON.stringify(report,null,2));
for(const gearProfile of ['sustain','shield'] as const)for(const routeChoice of ['rest-shrine','elite-shortcut'] as const)for(const composition of STORY_COMPOSITIONS)for(const floor of [9,12,15]){
 report.alternateGear.push(simulateStoryFloor(floor,4,12,undefined,composition,true,{gearProfile,routeChoice}));save();
}
for(const routeChoice of ['rest-shrine','elite-shortcut'] as const)for(const floor of [1,9,15]){
 report.lowerPowerControls.push(simulateStoryFloor(floor,4,12,undefined,'mixed',true,{gearProfile:'catalog-control',routeChoice}));save();
}
report.finishedAt=new Date().toISOString();save();console.log('Completed '+report.alternateGear.length+' alternate rows');

import {readFileSync,writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
const read=(p:string)=>JSON.parse(readFileSync(p,'utf8'));
const paths=Object.keys(read('.tmp/tower-pve-24d-curve-source.json').sourceHashes);
const hashes=()=>Object.fromEntries(paths.map(p=>[p,createHash('sha256').update(readFileSync(p)).digest('hex')]));
const before=hashes(),source=execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8',windowsHide:true}).trim(),startedAt=new Date().toISOString();
const expected=process.argv.find(a=>a.startsWith('--source='))?.slice(9)??'925f95d8033ff08b3bb7c2c2c4171a1d0f810ffe';
if(source!==expected)throw Error('Unexpected combined source');
const expanded=JSON.parse(readFileSync('.tmp/tower-pr511-dependency-audit.json','utf8'));
if(expanded.source!==source)throw Error('Expanded dependency audit must match the matrix source');
const expandedHashes=()=>Object.fromEntries(Object.keys(expanded.sourceHashes).map(p=>[p,createHash('sha256').update(readFileSync(p)).digest('hex')]));
if(JSON.stringify(expanded.sourceHashes)!==JSON.stringify(expandedHashes()))throw Error('Expanded model inputs changed before matrix');
await import('./tower-pve-combined-main-matrix.mts');
await import('./tower-pve-combined-main-alternates.mts');
const unchanged=JSON.stringify(before)===JSON.stringify(hashes())&&JSON.stringify(expanded.sourceHashes)===JSON.stringify(expandedHashes());
writeFileSync('.tmp/tower-pve-combined-main-curve-source.json',JSON.stringify({source,startedAt,finishedAt:new Date().toISOString(),sourceHashes:before,expandedSourceHashes:expanded.sourceHashes,unchanged,node:process.version},null,2)+'\n');
if(!unchanged)throw Error('Model sources changed during combined-main probe');

