import {readFileSync,writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
const comparison=JSON.parse(readFileSync('.tmp/tower-pve-comparison-final.json','utf8'));
const hash=()=>Object.fromEntries(Object.keys(comparison.sourceHashes).map(path=>[path,createHash('sha256').update(readFileSync(path)).digest('hex')]));
const before=hash(),startedAt=new Date().toISOString();
if(JSON.stringify(before)!==JSON.stringify(comparison.sourceHashes))throw Error('Comparison sources changed');
await import('./tower-pve-matrix-current.mts');
await import('./tower-pve-alternates-current.mts');
const after=hash();
writeFileSync('.tmp/tower-pve-current-curve-source.json',JSON.stringify({startedAt,finishedAt:new Date().toISOString(),sourceHashes:before,
    unchanged:JSON.stringify(before)===JSON.stringify(after),node:process.version},null,2)+'\n');
if(JSON.stringify(before)!==JSON.stringify(after))throw Error('Sources changed while refreshing route matrix');

